26	    public static LocalDate effectiveRegistrationDate(LocalDate supplied) {
27	        return toBusinessDay(supplied != null ? supplied : LocalDate.now());
28	    }
29	
30	    /**
31	     * The number of owners already registered on the given business day. Single source of truth for
32	     * the per-day signup count, shared by the daily-limit and bulk-signup rules so their counts
33	     * cannot drift apart; each rule keeps only its own threshold and action. Counts persisted owners
34	     * only, so a step calling this before {@code SaveOwner} does not count the owner being created.
35	     */
36	    public static long createdOn(OwnerRepository ownerRepository, LocalDate businessDay) {
37	        return ownerRepository.findAll().stream()
38	                .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
39	                .count();
40	    }
41	
42	    /** Roll a weekend date forward to the next Monday; weekdays are returned unchanged. */
43	    public static LocalDate toBusinessDay(LocalDate date) {
44	        LocalDate adjusted = date;
45	        while (adjusted.getDayOfWeek() == DayOfWeek.SATURDAY
46	                || adjusted.getDayOfWeek() == DayOfWeek.SUNDAY) {
47	            adjusted = adjusted.plusDays(1);
48	        }
